namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class InnerRuntimeFilesystemConfigurationFactory(Action<Humidifier.BedrockAgentCore.RuntimeTypes.FilesystemConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.RuntimeTypes.FilesystemConfiguration>
{

    internal InnerRuntimeCapacityProviderVolumeConfigurationFactory CapacityProviderVolumeFactory { get; set; }

    internal InnerRuntimeS3FilesAccessPointConfigurationFactory S3FilesAccessPointFactory { get; set; }

    internal InnerRuntimeSessionStorageConfigurationFactory SessionStorageFactory { get; set; }

    internal InnerRuntimeEfsAccessPointConfigurationFactory EfsAccessPointFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.RuntimeTypes.FilesystemConfiguration Create()
    {
        var filesystemConfigurationResult = CreateFilesystemConfiguration();
        factoryAction?.Invoke(filesystemConfigurationResult);

        return filesystemConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.RuntimeTypes.FilesystemConfiguration CreateFilesystemConfiguration()
    {
        var filesystemConfigurationResult = new Humidifier.BedrockAgentCore.RuntimeTypes.FilesystemConfiguration();

        return filesystemConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.RuntimeTypes.FilesystemConfiguration result)
    {
        base.CreateChildren(result);

        result.CapacityProviderVolume ??= CapacityProviderVolumeFactory?.Build();
        result.S3FilesAccessPoint ??= S3FilesAccessPointFactory?.Build();
        result.SessionStorage ??= SessionStorageFactory?.Build();
        result.EfsAccessPoint ??= EfsAccessPointFactory?.Build();
    }

} // End Of Class

